-- Subject value: the pilot's missions, hazard <= subject.clearance AND (no certification OR certification IN subject.certifications).
SELECT Id, SectorId, ClientId, KindId, Title, Brief, Hazard, Fee, Deadline, RequiredCertId, BookedBy, AssignedSquadronId, StatusId, Notes FROM Missions WHERE (`Missions`.`SectorId` = 'anvil') AND ((`Missions`.`Hazard` <= (SELECT `ca1`.`Clearance` FROM `Pilots` `ca1` WHERE `ca1`.`UserId` = 'pilot') AND (`Missions`.`RequiredCertId` IS NULL OR EXISTS (SELECT 1 FROM `PilotCertifications` `ca2` WHERE `ca2`.`UserId` = 'pilot' AND `ca2`.`CertificationId` = `Missions`.`RequiredCertId`)))) ORDER BY `Deadline` ASC, `Id` ASC LIMIT 26
